{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C57"],
      "claim": "Dabrafenib has a mean absolute oral bioavailability of 95% in humans; its high transfer score and shared sulfonamide/difluorophenyl/fluorophenyl features support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Cerivastatin absolute bioavailability is 60% (90% CI 51–70%) in healthy young men, a direct human absolute F measurement well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C80"],
      "claim": "Trovafloxacin mean absolute oral bioavailability is 87.6% (range 64.8–122.1%) in fasting healthy volunteers, supporting high F for this difluorophenyl-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Lumiracoxib oral bioavailability is 74.0 ± 8.6% in healthy subjects using an IV reference, supporting high F for a fluorophenyl-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Rufinamide absolute oral bioavailability is approximately 85% in humans, supporting high F for a difluorobenzyl-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Voriconazole absolute bioavailability is 83.3% ± 13.9% in subjects, supporting high F for a difluorophenyl-containing azole.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Safinamide absolute oral bioavailability is about 95% (90% CI 90–99%) in healthy subjects, supporting high F for a fluorobenzyl-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C67"],
      "claim": "Esaxerenone absolute bioavailability is 89.0% (90% CI 86.7–91.5%) in fasting healthy Japanese subjects, supporting high F for a sulfonyl/fluorophenyl-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "Gliborunide mean absolute bioavailability is 91% (range 61–112%) in normal subjects, supporting high F for a sulfonamide/fluorophenyl-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "CC-292 demonstrated excellent oral bioavailability in a Phase IA human study, supporting high F for a fluorophenyl/heteroaromatic drug.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All ten high-transfer analogues have human oral bioavailability values of 60–95% (or 'excellent'), far above the 20% threshold. The query shares fluorinated aryl, sulfonamide/sulfonyl, and heteroaromatic features with these compounds. No affirmative evidence supports low F; therefore predict high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule itself.",
    "Some records are not explicitly absolute bioavailability or are from unspecified report types, but the strongest records are absolute human studies.",
    "No specific data on the query's solubility, permeability, or first-pass metabolism; however, the consistent high-F analogue evidence outweighs generic concerns."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

